use clap::Args;
use clap::Parser;
use clap::Subcommand;
use clap::error::ErrorKind;

fn parse_define(raw: &str) -> Result<String, String> {
    if raw.contains('=') {
        Ok(raw.to_owned())
    } else {
        Err(format!("invalid define `{raw}`: expected key=value"))
    }
}

#[derive(Parser, Debug, PartialEq, Clone)]
#[command(name = "tool", override_usage = "tool [OPTIONS] <COMMAND>")]
struct Cli {
    #[arg(long, global = true, default_value = "builtin.toml", value_name = "path")]
    config: String,
    #[arg(long, global = true, value_name = "key=value", value_parser = parse_define)]
    define: Vec<String>,
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug, PartialEq, Clone)]
enum Commands {
    Serve(ServeArgs),
    Check(CheckArgs),
    #[command(external_subcommand)]
    External(Vec<String>),
}

#[derive(Args, Debug, PartialEq, Clone)]
#[command(override_usage = "tool serve [OPTIONS] <COMMAND>")]
struct ServeArgs {
    #[command(subcommand)]
    command: ServeCommands,
}

#[derive(Subcommand, Debug, PartialEq, Clone)]
enum ServeCommands {
    Worker(WorkerArgs),
    #[command(external_subcommand)]
    External(Vec<String>),
}

#[derive(Args, Debug, PartialEq, Clone)]
#[command(override_usage = "tool serve worker [OPTIONS] --port <PORT> [-- <TRAILING>...]")]
struct WorkerArgs {
    #[arg(long, value_name = "PORT", required = true, value_parser = clap::value_parser!(u16).range(1..))]
    port: u16,
    #[arg(long, conflicts_with = "udp")]
    tcp: bool,
    #[arg(long, conflicts_with = "tcp")]
    udp: bool,
    #[arg(last = true)]
    trailing: Vec<String>,
}

#[derive(Args, Debug, PartialEq, Clone)]
#[command(override_usage = "tool check [OPTIONS] [PATH]")]
struct CheckArgs {
    #[arg(long)]
    strict: bool,
    #[arg(value_name = "PATH")]
    path: Option<String>,
}

fn show(argv: &[&str]) {
