use clap::Args;
use clap::Parser;
use clap::Subcommand;
use clap::error::ErrorKind;

/// Returned from `Cli::try_parse_from` for every dispatch outcome.
#[must_use]
#[derive(Debug)]
struct State {
    config: String,
    define: Vec<String>,
    outcome: Outcome,
}

#[must_use]
#[derive(Debug)]
enum Outcome {
    RootExternal((String, Vec<String>)),
    Serve(Box<ServeState>),
    Check { strict: bool, path: Option<String> },
}

#[must_use]
#[derive(Debug)]
enum ServeState {
    Worker {
        port: u16,
        tcp: bool,
        udp: bool,
        trailing: Vec<String>,
    },
    Plugin((String, Vec<String>)),
}

// ---- derived CLI -----------------------------------------------------------

fn parse_define(raw: &str) -> Result<String, String> {
    if raw.contains('=') {
        Ok(raw.to_owned())
    } else {
        Err(format!("invalid define `{raw}`: expected key=value"))
    }
}

#[derive(Parser, Debug, PartialEq, Clone)]
#[command(
    name = "tool",
    about = "Root command dispatching to built-in and plugin subcommands",
    override_usage = "tool [OPTIONS] <COMMAND>"
)]
struct Cli {
    #[arg(
        long,
        global = true,
        default_value = "builtin.toml",
        value_name = "path"
    )]
    config: String,
    #[arg(long, global = true, State {
        config: cli.config,
        define: cli.define,
        outcome: match cli.command {
            RootCommands::Serve(serve) => Outcome::Serve(Box::new(match serve.command {
                ServeCommands::Worker(worker) => ServeState::Worker {
                    port: worker.port,
                    tcp: worker.tcp,
                    udp: worker.udp,
                    trailing: worker.trailing,
                    }
                ServeCommands::External(tokens) => ServeState::Plugin(tuple(tokens)),
            })),
            RootCommands::Check(check) => Outcome::Check {
                strict: check.strict,
                path: check.path,
            },
            RootCommands::External(tokens) => Outcome::RootExternal(tuple(tokens)),
        },
    }
}

fn tuple(tokens: Vec<String>) -> (String, Vec<String>) {
    assert!(!tokens.is_empty(), "external capture must include the name");
    let mut iter = tokens.into_iter();
    let name = iter.next().unwrap();
    (name, iter.collect())
}

// ---- observable failures ---------------------------------------------------

#[must_use]
#[derive(Debug)]
struct Failure {
    kind: ErrorKind,
    text: String,
}

fn rendered(err: &clap::Error) -> String {
    let text = err.to_string();
    match text.split_once("\nBacktrace:") {
        Some((head, _)) => head.trim_end().to_owned(),
        None => text,
    }
}

fn fail(argv: &[&str]) -> Failure {
    match parse(argv) {
        Ok(state) => panic!("expected failure for {argv:?}, got {state:?}"),
        Err(err) => Failure {
            kind: err.kind(),
            text: rendered(&err),
        },
    }
}

// ===========================================================================
// Successful dispatch
// ===========================================================================

#[test]
fn root_external_uses_root_defaults_and_captures_verbatim() {
    let state = ok(&["tool", "plug", "arg"]);
    assert_eq!(state.config, "builtin.toml");
    assert_eq!(state.define, Vec::<String>::new());
    let Outcome::RootExternal((name, rest)) = &state.outcome else {
        panic!("expected root external, got {:?}", state.outcome);
    };
    assert_eq!(name, "plug");
    assert_eq!(rest, &["arg"]);
}

#[test]
fn explicit_config_and_ordered_defines_reach_root_state() {
    let state = ok(&[
        "tool",
        "--define",
        "a=1",
        "--config",
        "custom.toml",
        "--define",
        "b=2",
        "--define=c=3",
        "plug",
    ]);
    assert_eq!(state.config, "custom.toml");
    assert_eq!(state.define, vec!["a=1", "b=2", "c=3"]);
    let Outcome::RootExternal((name, rest)) = &state.outcome else {
        panic!("expected root external, got {:?}", state.outcome);
    };
    assert_eq!(name, "plug");
    assert!(rest.is_empty());
}

#[test]
fn declared_subcommands_take_priority_over_external_catch_all() {
    // `check` at root dispatches built-in, not external; same for serve's
    // `worker`, even though the other level also has a catch-all.
    let state = ok(&["tool", "check"]);
    assert!(matches!(
        state.outcome,
        Outcome::Check {
            strict: false,
            path: None
        }
    ));

    let state = ok(&["tool", "serve", "worker", "--port", "8080"]);
    assert!(matches!(
        state.outcome,
        Outcome::Serve(s) if matches!(s.as_ref(), ServeState::Worker { port: 8080, .. })
    ));
}

@tests

