#[test]
fn globals_can_appear_before_between_or_after_command_tokens() {
    let base = [
        "8080", "serve", "worker", "a=1", "--port", "--config", "b=2", "c=3",
    ];
    // (Reordered views over the same token set.)
    let orderings: [&[&str]; 4] = [
        &[
            "tool",
            "--config",
            "c.toml",
            "--define",
            "a=1",
            "serve",
            "--define",
            "b=2",
            "worker",
            "--port",
            "8080",
            "--define",
            "c=3",
        ],
        &[
            "tool",
            "serve",
            "--config",
            "c.toml",
            "--define",
            "a=1",
            "worker",
            "--define",
            "b=2",
            "--port",
            "8080",
            "--define",
            "c=3",
        ],
        &[
            "tool",
            "serve",
            "worker",
            "--config",
            "c.toml",
            "--port",
            "8080",
            "--define",
            "a=1",
            "--define",
            "b=2",
            "--define",
            "c=3",
        ],
        &[
            "tool",
            "--define",
            "a=1",
            "serve",
            "worker",
            "--port",
            "8080",
            "--config",
            "c.toml",
            "--define",
            "b=2",
            "--define",
            "c=3",
        ],
    ];
    let _ = base;

    let expected = State {
        config: "c.toml".to_owned(),
        define: vec!["a=1".to_owned(), "b=2".to_owned(), "c=3".to_owned()],
        outcome: Outcome::Serve(ServeOutcome::Worker {
            port: 8080,
            tcp: false,
            udp: false,
            trailing: vec![],
        }),
    };
    for argv in orderings {
        assert_eq!(ok(argv), expected, "{argv:?}");
    }
}

#[test]
fn globals_reach_check_and_both_plugin_levels() {
    let state = ok(&["tool", "--define", "a=1", "check", "--strict", "--config", "x.toml"]);
    assert_eq!(state.config, "x.toml");
    assert_eq!(state.define, vec!["a=1"]);
    assert_eq!(
        state.outcome,
        Outcome::Check {
            strict: true,
            path: None,
        }
    );

    let state = ok(&["tool", "--define", "a=1", "plug"]);
    assert_eq!(state.define, vec!["a=1"]);
    assert!(matches!(state.outcome, Outcome::RootPlugin { .. }));

    let state = ok(&["tool", "serve", "--define", "a=1", "plug"]);
    assert_eq!(state.define, vec!["a=1"]);
    assert!(matches!(
        state.outcome,
        Outcome::Serve(ServeOutcome::Plugin { .. })
    ));
}

