#[test]
fn worker_and_serve_arguments_are_unknown_to_check() {
    for argv in [
        &["tool", "check", "--port", "80"][..],
        &["tool", "check", "--tcp"][..],
        &["tool", "check", "--udp"][..],
    ] {
        let f = fail(argv);
        assert_eq!(f.kind, ErrorKind::UnknownArgument, "{argv:?}");
        assert!(
            f.text.contains("tool check"),
            "{argv:?} lost check context:\n{}",
