1	//! Standalone, executable regression target for layered subcommand and plugin
2	//! dispatch.
3	//!
4	//! This file is a self-contained test target, in the style of `task015.rs`,
5	//! that depends on no private test module. It defines its own derived CLI and
6	//! observes every result solely through the public `clap::Parser` API via
7	//! `Cli::try_parse_from` (argv0 included): successful structures, typed errors,
8	//! and rendered help text.
9	//!
10	//! Scenario under test:
11	//! * root command `tool` with a default config path and repeatable
12	//!   `--define` items, both global, declaring `serve` and `check` while keeping
13	//!   a root-level external-subcommand catch-all;
14	//! * `serve` declares `worker` and hands every other name to its own external
15	//!   plugin catch-all;
16	//! * `worker` requires a unique `--port` that is a decimal number in
17	//!   `1..=65535`, has mutually exclusive `--tcp`/`--udp` switches, and stores
18	//!   trailing arguments after its own `--` verbatim;
19	//! * `check` accepts only one optional path and `--strict`, inheriting none of
20	//!   `serve`/`worker`'s arguments;
21	//! * global config/definitions may appear before, between, or after the
22	//!   command tokens, with the explicit config overriding the default and
23	//!   definitions kept in command-line order;
24	//! * declared subcommands win over external capture, but once an external name
25	//!   is chosen every following token belongs to that plugin;
26	//! * a root-level `--` names an external command, while `worker`'s `--` only
27	//!   produces trailing arguments;
28	//! * validation failures name the most specific command and the triggering
29	//!   token and distinguish missing, invalid-value, conflict, and unknown-token
30	//!   cases, leaving nothing partially populated that a later parse could read;
31	//! * help at every level succeeds while required values are missing;
32	//! * a fixed sequence of root-plugin success, serve-plugin success, invalid
33	//!   input, worker success, and help is mutually isolated, and merely moving
34	//!   global arguments around changes neither the parsed structure, trailing
35	//!   order, error usage, nor the order of definitions in help.
36	#![cfg(feature = "derive")]
37	#![cfg(feature = "help")]
38	#![cfg(feature = "usage")]
39	
40	use clap::Args;
41	use clap::Parser;
42	use clap::Subcommand;
43	use clap::error::ErrorKind;
44	
45	// ---- command-line surface --------------------------------------------------
46	
47	fn parse_define(raw: &str) -> Result<String, String> {
48	    if raw.contains('=') {
49	        Ok(raw.to_owned())
50	    } else {
51	        Err(format!("invalid define `{raw}`: expected key=value"))
52	    }
53	}
54	
55	#[derive(Parser, Debug, PartialEq, Clone)]
56	#[command(
57	    name = "tool",
58	    about = "Root command dispatching to built-in and plugin subcommands",
59	    override_usage = "tool [OPTIONS] <COMMAND>"
60	)]
61	struct Cli {
62	    #[arg(
63	        long,
64	        global = true,
65	        default_value = "builtin.toml",
66	        value_name = "path"
67	    )]
68	    config: String,
69	    #[arg(long, global = true, value_name = "key=value", value_parser = parse_define)]
70	    define: Vec<String>,
71	    #[command(subcommand)]
72	    command: RootCommands,
73	}
74	
75	#[derive(Subcommand, Debug, PartialEq, Clone)]
76	enum RootCommands {
77	    #[command(about = "Serve traffic")]
78	    Serve(ServeArgs),
79	    #[command(about = "Check a project")]
80	    Check(CheckArgs),
81	    #[command(external_subcommand)]
82	    External(Vec<String>),
83	}
