127	// ---- observed outcome -------------------------------------------------------
128	
129	/// Every observation the tests make, flattened out of the derived tree so the
130	/// assertions read against the spec rather than the enum nesting.
131	#[derive(Debug, PartialEq, Clone)]
132	struct State {
133	    config: String,
134	    define: Vec<String>,
135	    outcome: Outcome,
136	}
137	
138	#[derive(Debug, PartialEq, Clone)]
139	enum Outcome {
140	    /// Root-level plugin: the external name plus its verbatim tokens.
141	    RootPlugin {
142	        name: String,
143	        tokens: Vec<String>,
144	    },
145	    Serve(ServeOutcome),
146	    Check {
147	        strict: bool,
148	        path: Option<String>,
149	    },
150	}
151	
152	#[derive(Debug, PartialEq, Clone)]
153	enum ServeOutcome {
154	    /// Serve-level plugin.
155	    Plugin { name: String, tokens: Vec<String> },
156	    Worker {
157	        port: u16,
158	        tcp: bool,
159	        udp: bool,
160	        trailing: Vec<String>,
161	    },
162	}
163	
164	impl State {
165	    fn from_cli(cli: Cli) -> Self {
166	        let Cli {
167	            config,
168	            define,
169	            command,
170	        } = cli;
171	        let outcome = match command {
172	            RootCommands::External(tokens) => {
173	                let (name, tokens) = split_name(tokens);
174	                Outcome::RootPlugin { name, tokens }
175	            }
176	            RootCommands::Check(CheckArgs { strict, path }) => Outcome::Check { strict, path },
177	            RootCommands::Serve(ServeArgs { command }) => Outcome::Serve(match command {
178	                ServeCommands::External(tokens) => {
179	                    let (name, tokens) = split_name(tokens);
180	                    ServeOutcome::Plugin { name, tokens }
181	                }
182	                ServeCommands::Worker(WorkerArgs {
183	                    port,
184	                    tcp,
185	                    udp,
186	                    trailing,
187	                }) => ServeOutcome::Worker {
188	                    port,
189	                    tcp,
190	                    udp,
191	                    trailing,
192	                },
193	            }),
194	        };
195	        Self {
196	            config,
197	            define,
198	            outcome,
199	        }
200	    }
201	}
202	
203	fn split_name(tokens: Vec<String>) -> (String, Vec<String>) {
204	    assert!(
205	        !tokens.is_empty(),
